UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Read the card, its comments and the code and data it touches, and check facts rather than planning from assumptions. Write the requirements: what changes and why, testable acceptance checks, and on its own line 'User-facing change: YES' or 'User-facing change: NO'. If YES, design the change as an HTML mock that matches the app's existing look and components, and attach it to the card; if the card already has an approved design, use it rather than redesigning. Say which platforms it targets (iOS, Android or both) and anything that must behave differently on each. Then write the technical plan the Build step will follow: the files to change and why, any data or interface changes, the tests to write, the risks, and the release order. If the work is too big for one change, split it into stages that each ship on their own and plan stage 1 in full. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary for whoever approves the plan: what will change, and each decision they need to make, with your recommendation.","deliverables":["Plain-English summary and decisions","Requirements with acceptance checks and the User-facing change line","Design mock attached to the card, if user-facing","Technical plan (stage 1 in full if staged)","Working-notes file"],"requires_approval":true},{"role":"Full Stack Engineer","title":"Build","model_tier":"standard","description":"Build the approved plan (stage 1 only, if it's staged), working from the Plan step's output and the working-notes file. Write failing tests first where practical. If the plan turns out to be wrong or incomplete, don't improvise: call fail_step with what you found and reset to Plan. If there's an approved mock, it's the source of truth for everything visual: compare what you built with it on a phone-sized simulator for each platform and fix every difference. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, the test and type-check results, and any deviations from the plan, with reasons.","deliverables":["Code and tests","PR link","Test and type-check results","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Device test and release summary","model_tier":"standard","description":"Test the change independently on a simulator or device for each platform in the plan, against every acceptance check and edge case it lists, including touch, rotation, slow or no network, and app store rules where the plan names them. If there's an approved mock, compare with it and attach the screenshots. Send any real failure back with fail_step and reset to Build. Then write the release summary in plain English: what's live, what you checked and how, and anything still needing a person. The release is approved from this step.","deliverables":["Test report per platform","Screenshots, if there's a mock","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Plan, build, check, release for a mobile app: one Planner writes the requirements (including platform scope), any design mock and the technical plan, and you approve it; a cheaper model builds it; an independent code review and device test follow; you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$Mobile App Feature$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Read the card, its comments and the code and data it touches, and check facts rather than planning from assumptions. Write the requirements: what changes and why, testable acceptance checks, and on its own line 'User-facing change: YES' or 'User-facing change: NO'. If YES, design the change as an HTML mock that matches the app's existing look and components, and attach it to the card; if the card already has an approved design, use it rather than redesigning. Contract first: put every endpoint in the plan before anything is built, with its request and response shapes, error codes and auth rules. A backend change usually has no screens, so there's normally no mock. Then write the technical plan the Build step will follow: the files to change and why, any data or interface changes, the tests to write, the risks, and the release order. If the work is too big for one change, split it into stages that each ship on their own and plan stage 1 in full. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary for whoever approves the plan: what will change, and each decision they need to make, with your recommendation.","deliverables":["Plain-English summary and decisions","Requirements with acceptance checks and the User-facing change line","Design mock attached to the card, if user-facing","Technical plan (stage 1 in full if staged)","Working-notes file"],"requires_approval":true},{"role":"Full Stack Engineer","title":"Build","model_tier":"standard","description":"Build the approved plan (stage 1 only, if it's staged), working from the Plan step's output and the working-notes file. Write contract tests for every endpoint in the plan before the code that serves them. Write failing tests first where practical. If the plan turns out to be wrong or incomplete, don't improvise: call fail_step with what you found and reset to Plan. If there's an approved mock, it's the source of truth for everything visual: compare what you built with it at 375px and 1280px wide and fix every difference. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, the test and type-check results, and any deviations from the plan, with reasons.","deliverables":["Code and tests","PR link","Test and type-check results","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Pay particular attention to auth, input validation and anything that could leak data. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Contract test and release summary","model_tier":"standard","description":"Call every endpoint in the contract independently, including the error cases and auth failures, and check every response matches the contract exactly. Run a load test only where the plan sets a performance target. Send any real failure back with fail_step and reset to Build. Then write the release summary in plain English: what's live, what you checked and how, and anything still needing a person. The release is approved from this step.","deliverables":["Contract test report","Load test results, if the plan set a target","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Contract first: one Planner writes the requirements, the API contract and the technical plan, and you approve them; a cheaper model builds against the contract; an independent code review and contract test follow; you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$API / Backend Feature$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Read the card, its comments and the code and data it touches, and check facts rather than planning from assumptions. Write the requirements: what changes and why, testable acceptance checks, and on its own line 'User-facing change: YES' or 'User-facing change: NO'. If YES, design the change as an HTML mock that matches the app's existing look and components, and attach it to the card; if the card already has an approved design, use it rather than redesigning. For an AI feature the plan also states the problem and a measurable success metric with the baseline to beat; the data it needs, with its quality, consent and privacy risks; and the evaluation: the test cases, including likely failure and bias cases, and how they're scored. Then write the technical plan the Build step will follow: the files to change and why, any data or interface changes, the tests to write, the risks, and the release order. If the work is too big for one change, split it into stages that each ship on their own and plan stage 1 in full. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary for whoever approves the plan: what will change, and each decision they need to make, with your recommendation.","deliverables":["Plain-English summary and decisions","Requirements with acceptance checks and the User-facing change line","Design mock attached to the card, if user-facing","Technical plan (stage 1 in full if staged)","Working-notes file"],"requires_approval":true},{"role":"Full Stack Engineer","title":"Build and evaluate","model_tier":"standard","description":"Build the approved plan (stage 1 only, if it's staged), working from the Plan step's output and the working-notes file. Prepare the data, build or prompt the model, and integrate it; then run the plan's evaluation and report the scores against the baseline. Write failing tests first where practical. If the plan turns out to be wrong or incomplete, don't improvise: call fail_step with what you found and reset to Plan. If there's an approved mock, it's the source of truth for everything visual: compare what you built with it at 375px and 1280px wide and fix every difference. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, the test and type-check results, and any deviations from the plan, with reasons.","deliverables":["Code and tests","PR link","Test and type-check results","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Include how prompts, keys and user data are handled. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Independent evaluation and release summary","model_tier":"standard","description":"Re-run the plan's evaluation yourself, adding held-out cases the builder didn't see, including the failure and bias cases the plan lists, and check the feature end to end where users meet it. If it misses the success metric or fails a case that matters, that counts as a real failure. Send any real failure back with fail_step and reset to Build. Then write the release summary in plain English: what's live, what you checked and how, and anything still needing a person. Include the scores against the baseline. The release is approved from this step.","deliverables":["Independent evaluation scores against the baseline","End-to-end check","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Plan, build and evaluate, check, release: one Planner sets the success metric, the data and the evaluation along with the technical plan, and you approve it; a cheaper model builds and evaluates it; an independent code review and an independent evaluation follow; you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$AI / ML Feature$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Read the card, its comments and the code and data it touches, and check facts rather than planning from assumptions. Write the requirements: what changes and why, testable acceptance checks, and on its own line 'User-facing change: YES' or 'User-facing change: NO'. If YES, design the change as an HTML mock that matches the app's existing look and components, and attach it to the card; if the card already has an approved design, use it rather than redesigning. For a component the plan also covers what already exists that overlaps (reuse before adding), its API (props and variants), every state, accessibility (keyboard, screen reader, contrast), and a mock of every variant and state. Then write the technical plan the Build step will follow: the files to change and why, any data or interface changes, the tests to write, the risks, and the release order. If the work is too big for one change, split it into stages that each ship on their own and plan stage 1 in full. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary for whoever approves the plan: what will change, and each decision they need to make, with your recommendation.","deliverables":["Plain-English summary and decisions","Requirements with acceptance checks and the User-facing change line","Design mock attached to the card, if user-facing","Technical plan (stage 1 in full if staged)","Working-notes file"],"requires_approval":true},{"role":"Front End Engineer","title":"Build and document","model_tier":"standard","description":"Build the approved plan (stage 1 only, if it's staged), working from the Plan step's output and the working-notes file. Write its documentation and usage examples alongside the code. Write failing tests first where practical. If the plan turns out to be wrong or incomplete, don't improvise: call fail_step with what you found and reset to Plan. If there's an approved mock, it's the source of truth for everything visual: compare what you built with it at 375px and 1280px wide and fix every difference. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, the test and type-check results, and any deviations from the plan, with reasons.","deliverables":["Code and tests","PR link","Test and type-check results","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Visual and accessibility test, and release summary","model_tier":"standard","description":"Test every variant and state independently against the mock at 375px and 1280px, with the keyboard only and with a screen reader, in the browsers the plan names, and attach the screenshots. Send any real failure back with fail_step and reset to Build. Then write the release summary in plain English: what's live, what you checked and how, and anything still needing a person. Write the changelog entry too. The release is approved from this step.","deliverables":["Test report per variant and state","Screenshots","Changelog entry","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Plan, build and document, check, release for one component: one Planner audits what exists and writes the component's spec and mock, and you approve it; a cheaper model builds and documents it; an independent code review and a visual and accessibility test follow; you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$Design System Component$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan: brief, copy and layout","model_tier":"frontier","description":"Do your Planner job for this page, all in this one conversation: the brief (who it's for, the one action we want them to take, and how we'll measure it); the page copy in full; and an HTML mock of the layout at phone and desktop width that matches the site's look, attached to the card. Then the build plan. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary and the decisions for whoever approves it: they approve the copy and the layout together here.","deliverables":["Brief","Page copy in full","Layout mock attached to the card","Build plan","Working-notes file"],"requires_approval":true},{"role":"Front End Engineer","title":"Build the page","model_tier":"standard","description":"Build the page from the approved copy and mock: the copy word for word, and the mock as the source of truth for everything visual. Compare at 375px and 1280px wide and fix every difference. If the copy or layout can't work as approved, call fail_step and reset to Plan. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR or preview link.","deliverables":["Page","PR or preview link","Deviations, with reasons"],"requires_approval":false},{"role":"QA Engineer","title":"Test and launch summary","model_tier":"standard","description":"Test the page independently: against the mock at 375px and 1280px (attach the screenshots), every link and form, basic accessibility, page speed, and a proofread against the approved copy. Send failures back with fail_step and reset to Build the page. Then write the launch summary in plain English. The launch is approved from this step.","deliverables":["Test report","Screenshots","Plain-English launch summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Brief, copy and layout planned and approved together, then built, then tested: three steps, one approval for the plan and one for launch.$tpl$,
    updated_at = now()
WHERE name = $tpl$Landing Page$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Write the mechanic brief: what the player does, what the game does back, and what 'feels right' means in one sentence. Name the single question the playtest must answer, and a cut line: the smallest version that answers it. Then write the technical plan the Build step will follow: the scripts and scenes to change, the tunable numbers and their starting values, and how it will be tested. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary and the decisions for whoever approves the plan.","deliverables":["Brief with the playtest question and cut line","Technical plan","Working-notes file","Plain-English summary and decisions"],"requires_approval":true},{"role":"Gameplay Programmer","title":"Build","model_tier":"standard","description":"Build the approved plan up to the cut line and no further, working from the Plan step's output and the working-notes file. Expose the tunable numbers the plan lists so they can be changed without code edits. If the plan turns out to be wrong, don't improvise: call fail_step with what you found and reset to Plan. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, what you tested, and any deviations from the plan, with reasons.","deliverables":["Code","PR link","What was tested","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA / Playtester","title":"Playtest and ship summary","model_tier":"standard","description":"Play it independently and answer the plan's playtest question with evidence: clips or screenshots, and what you did. If it needs tuning or fixing, send it back with fail_step and reset to Build, as a numbered list of specific changes (numbers, not adjectives). Then write the ship summary in plain English. Shipping is approved from this step.","deliverables":["Playtest answer with evidence","Tuning list, if sent back","Plain-English ship summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Ship one mechanic: one Planner writes the brief, the playtest question, the cut line and the technical plan, and you approve it; a cheaper model builds to the cut line; an independent code review and playtest follow; you approve shipping. Tuning goes back to Build.$tpl$,
    updated_at = now()
WHERE name = $tpl$Game Feature / Mechanic$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Write the behaviour brief: what the enemy wants, what it can sense, its states and what moves it between them, and how the player can tell what it's about to do. Name the single question the playtest must answer, and a cut line: the smallest version that answers it. Then write the technical plan the Build step will follow: the scripts and scenes to change, the tunable numbers and their starting values, and how it will be tested. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary and the decisions for whoever approves the plan.","deliverables":["Brief with the playtest question and cut line","Technical plan","Working-notes file","Plain-English summary and decisions"],"requires_approval":true},{"role":"Enemy AI Engineer","title":"Build","model_tier":"standard","description":"Build the approved plan up to the cut line and no further, working from the Plan step's output and the working-notes file. Expose the tunable numbers the plan lists so they can be changed without code edits. If the plan turns out to be wrong, don't improvise: call fail_step with what you found and reset to Plan. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, what you tested, and any deviations from the plan, with reasons.","deliverables":["Code","PR link","What was tested","Deviations from the plan, with reasons"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the PR independently against the approved plan and the working-notes file. You didn't build it, and you don't edit code. Check that it does what the plan says and nothing it doesn't. Look for bugs, security issues, whether the tests would catch a regression, and the project's conventions. Send blocking issues back with fail_step as a numbered list: reset to Build for code problems, or to Plan if the plan itself was wrong. Start your output with 'Pass' or 'Blocked'; put non-blocking notes after it.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA / Playtester","title":"Playtest and ship summary","model_tier":"standard","description":"Play it independently and answer the plan's playtest question with evidence: clips or screenshots, and what you did, including whether a player can read and counter the behaviour. If it needs tuning or fixing, send it back with fail_step and reset to Build, as a numbered list of specific changes (numbers, not adjectives). Then write the ship summary in plain English. Shipping is approved from this step.","deliverables":["Playtest answer with evidence","Tuning list, if sent back","Plain-English ship summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$One enemy behaviour: one Planner writes the behaviour brief and the technical plan, and you approve it; a cheaper model builds it; an independent code review and playtest follow; you approve shipping.$tpl$,
    updated_at = now()
WHERE name = $tpl$Enemy AI Behaviour$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan: content brief","model_tier":"frontier","description":"Do your Planner job for this card, all in this one conversation. Write the content brief: what this level or content is for, its pacing and how the player finds their way, the art and audio direction, and the performance budget. Then the build plan: block-out first, then the art and audio passes. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary and the decisions for whoever approves the plan.","deliverables":["Content brief","Build plan","Working-notes file","Plain-English summary and decisions"],"requires_approval":true},{"role":"Level / Environment Designer","title":"Build the level","model_tier":"standard","description":"Build the approved plan. Block out the space and play it yourself before any art; then do the art and audio passes the plan lists, staying within the performance budget. If the plan doesn't work once it's playable, call fail_step and reset to Plan. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link, before-and-after screenshots, and the frame-time figures.","deliverables":["Level built to the plan","PR link","Screenshots","Frame-time figures"],"requires_approval":false},{"role":"QA / Playtester","title":"Playtest and sign-off summary","model_tier":"standard","description":"Play it independently: can a new player find their way, does the pacing match the brief, do the art and audio read clearly, and does it stay within the budget? Send problems back with fail_step and reset to Build the level, as a numbered list of specific changes. Then write the sign-off summary in plain English. It's approved from this step.","deliverables":["Playtest report with evidence","Plain-English sign-off summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$One level or piece of content: one Planner writes the content brief and build plan, and you approve it; the level designer builds it (block-out, then the art and audio passes); an independent playtest follows; you sign it off.$tpl$,
    updated_at = now()
WHERE name = $tpl$Level / Content$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Investigate and plan the fix","model_tier":"frontier","description":"Reproduce the bug and write down the exact steps. Find the root cause, not just where the symptom shows: explain why it happens, and name the scripts or scenes involved and the fix you recommend. If you can't reproduce it, say so plainly with the evidence you do have; don't present a guess as confirmed. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it.","deliverables":["Reproduction steps","Root cause","Fix plan","Working-notes file"],"requires_approval":false},{"role":"Gameplay Programmer","title":"Fix","model_tier":"standard","description":"Fix the root cause from the investigation. Test first where the engine allows: a test or a repeatable reproduction that fails before the fix and passes after. If the cause turns out to be different, don't patch the symptom: call fail_step and reset to Investigate and plan the fix. Keep the change to the bug. Add what you decided and why to the working-notes file, and commit it with your work. Return the PR link and the before-and-after evidence.","deliverables":["Fix","PR link","Before-and-after evidence"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the fix independently against the root cause in the investigation and the working-notes file. You don't edit code. Check that it fixes the cause rather than the symptom, that the regression test really fails without the fix, and look for security issues, test quality, project conventions and scope creep. Send blocking issues back with fail_step as a numbered list: reset to Fix, or to Investigate and plan the fix if the diagnosis is wrong. Start your output with 'Pass' or 'Blocked'.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA / Playtester","title":"Regression playtest and summary","model_tier":"standard","description":"Follow the original reproduction and confirm the bug is gone, then play the areas around the change for anything it broke. Send failures back with fail_step and reset to Fix. Then write the summary in plain English. The fix is approved from this step.","deliverables":["Regression playtest report","Plain-English summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Diagnose, fix, check, verify: the Planner finds the root cause, a cheaper model fixes it, an independent code review and regression playtest follow, and you approve the fix.$tpl$,
    updated_at = now()
WHERE name = $tpl$Game Bug Fix$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Milestone checklist","model_tier":"frontier","description":"Write what must be in this milestone's playable build, how each item will be checked, and what would make it a no-go. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it.","deliverables":["Milestone checklist with how each item is checked","No-go conditions","Working-notes file"],"requires_approval":false},{"role":"Gameplay Programmer","title":"Playable build","model_tier":"standard","description":"Make a playable build that meets the checklist. Fix only what blocks a checklist item and list everything else as known issues. Add what you decided and why to the working-notes file, and commit it with your work. Return where the build is, what's in it, and the known issues.","deliverables":["Playable build","What's in it","Known issues"],"requires_approval":false},{"role":"QA / Playtester","title":"Milestone review and go/no-go","model_tier":"frontier","description":"Play the build against every checklist item and record the evidence for each. Recommend go or no-go, with the reasons and the known issues that matter. The go or no-go decision is made from this step.","deliverables":["Evidence per checklist item","Go or no-go recommendation"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Checklist, playable build, review: you make the go or no-go decision once, at the end.$tpl$,
    updated_at = now()
WHERE name = $tpl$Milestone Gate$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Research and recommend","model_tier":"frontier","description":"Answer the card's question, all in this one conversation. First write down the question, what 'good enough' looks like, and a time limit. Then investigate: read the code, read the docs and cite the links, and build a throwaway prototype in a scratch scene if that's the quickest way to find out. End with the options, their trade-offs, your pick and why, and what would change your mind. Draft the follow-up cards it would need (a title and one line each), but don't create them. Begin your output with a plain-English summary and the decision for whoever approves it.","deliverables":["Question, good-enough bar and time limit","Findings with links","Options, trade-offs and recommendation","Draft follow-up cards"],"requires_approval":true},{"role":"Planner","title":"Record the decision","model_tier":"cheap","description":"Read the approval note and the research output. Fold the decision and the reasons into the card's description, and create the follow-up cards the approver chose, each linking back to this card. Don't reopen the research.","deliverables":["Card description updated with the decision","Follow-up cards created"],"requires_approval":false}]$tpl$::jsonb,
    description = $tpl$One research step that ends in a recommendation you approve, then the decision is written onto the card.$tpl$,
    updated_at = now()
WHERE name = $tpl$Game Technical Spike$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Research and recommend","model_tier":"frontier","description":"Answer the card's question, all in this one conversation. First write down the question, what 'good enough' looks like, and a time limit. Then investigate: read the code, read the docs and cite the links, and build a throwaway prototype in a scratch folder if that's the quickest way to find out. End with the options, their trade-offs, your pick and why, and what would change your mind. Draft the follow-up cards it would need (a title and one line each), but don't create them. Begin your output with a plain-English summary and the decision for whoever approves it.","deliverables":["Question, good-enough bar and time limit","Findings with links","Options, trade-offs and recommendation","Draft follow-up cards"],"requires_approval":true},{"role":"Planner","title":"Record the decision","model_tier":"cheap","description":"Read the approval note and the research output. Fold the decision and the reasons into the card's description, and create the follow-up cards the approver chose, each linking back to this card. Don't reopen the research.","deliverables":["Card description updated with the decision","Follow-up cards created"],"requires_approval":false}]$tpl$::jsonb,
    description = $tpl$One research step that ends in a recommendation you approve, then the decision is written onto the card and the follow-up cards are made.$tpl$,
    updated_at = now()
WHERE name = $tpl$Technical Spike$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Investigate and plan the fix","model_tier":"frontier","description":"Reproduce the bug and write down the exact steps. Find the root cause, not just where the symptom shows: trace it through the code, explain why it happens, and say when it started if the data shows it. Name the files and functions involved, the fix you recommend, the regression test that will prove it, and anything else that shares the same cause. If you can't reproduce it, say so plainly with the evidence you do have; don't present a guess as confirmed. If the fix would change what users see, or touches stored data, auth or payments, say so at the top. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it.","deliverables":["Reproduction steps","Root cause","Fix plan and the regression test that proves it","Working-notes file"],"requires_approval":false},{"role":"Full Stack Engineer","title":"Fix","model_tier":"standard","description":"Fix the root cause from the investigation and the working-notes file. Test first: write a test that reproduces the bug and fails before you change any code, then make it pass. If the root cause turns out to be different, don't patch the symptom: call fail_step with what you found and reset to Investigate and plan the fix. Keep the change to the bug. Add what you decided and why to the working-notes file, and commit it with your work. Your output names the test that failed and then passed, and confirms the full test suite and type checker pass.","deliverables":["Fix and regression test (failed before, passes after)","PR link","Test suite and type checker passing"],"requires_approval":false},{"role":"Code Reviewer","title":"Code review","model_tier":"frontier","description":"Review the fix independently against the root cause in the investigation and the working-notes file. You don't edit code. Check that it fixes the cause rather than the symptom, that the regression test really fails without the fix, and look for security issues, test quality, project conventions and scope creep. Send blocking issues back with fail_step as a numbered list: reset to Fix, or to Investigate and plan the fix if the diagnosis is wrong. Start your output with 'Pass' or 'Blocked'.","deliverables":["Review report: Pass or numbered blocking issues"],"requires_approval":false},{"role":"QA Engineer","title":"Verify and release summary","model_tier":"standard","description":"Check the fix independently of the builder. Follow the original reproduction, on the live site if it has been released, otherwise on a local or preview build, and confirm the bug is gone. Read the regression test and confirm it would fail if the bug came back. Check the behaviour around the change. Send failures back with fail_step: reset to Fix, or to Investigate and plan the fix if the diagnosis was wrong. Then write the release summary in plain English: what's fixed, how you checked, and anything still needing a person. The release is approved from this step.","deliverables":["Verification against the original reproduction","Nearby behaviour checked","Plain-English release summary"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$Diagnose, fix, check, verify: the Planner finds the root cause and plans the fix, a cheaper model fixes it test-first, an independent code review and an independent verification follow, and you approve the release.$tpl$,
    updated_at = now()
WHERE name = $tpl$Bug Fix$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Plan","model_tier":"frontier","description":"Do your Planner job for this change, all in this one conversation: what changes and why; what it affects and the risks; the step-by-step plan; the health checks that will prove it worked; and how to roll it back. Say where each part runs (local, preview, production) and in what order. Approving this plan approves deploying it exactly as written. Start the working-notes file for this card at docs/notes/<first 8 characters of the card id>.md: what you decided, why, what you ruled out, and where things are. The next step reads it. Begin your output with a plain-English summary and the decisions for whoever approves the plan.","deliverables":["Plain-English summary and decisions","Impact and risks","Step-by-step plan with health checks","Rollback steps","Working-notes file"],"requires_approval":true},{"role":"DevOps Engineer","title":"Implement, deploy and check","model_tier":"standard","description":"Carry out the approved plan exactly. Implement and test it; where a test or local copy allows, rehearse the rollback first (apply, roll back, re-apply). Then deploy as the plan says and run every health check in it, reporting the evidence for each. If a check fails, roll back by the plan and call fail_step with what happened. If anything comes up that the plan doesn't cover, stop and call fail_step with reset to Plan: don't improvise on a live system. Add what you decided and why to the working-notes file, and commit it with your work.","deliverables":["Change implemented and deployed","Evidence for every health check","Rollback rehearsal result, where possible"],"requires_approval":false}]$tpl$::jsonb,
    description = $tpl$Plan, then do: the Planner writes the change, its risks, the health checks and the rollback, and you approve it, which approves deploying it as written; the DevOps agent then implements, deploys and checks it, rolling back by the plan if a check fails.$tpl$,
    updated_at = now()
WHERE name = $tpl$Infrastructure Change$tpl$;

UPDATE public.workflow_library_templates
SET steps = $tpl$[{"role":"Planner","title":"Research and recommend: go or no-go","model_tier":"frontier","description":"Research this idea, all in this one conversation. Look at the market and the competitors: search the web and cite a link for every claim, and label anything that comes from your own knowledge as 'unverified'. Don't invent users, interviews or quotes. If interview notes are attached to the card, work only from them and cite them; otherwise list the assumptions only real users can confirm, with the question to ask for each. End with go, no-go, or 'test first' with the cheapest test that would decide it, and why. Begin with a plain-English summary for whoever decides.","deliverables":["Market and competitor findings, each with a link","Assumptions to test with real users","Go, no-go or test-first recommendation"],"requires_approval":true}]$tpl$::jsonb,
    description = $tpl$One research step, with sources, that ends in a go, no-go or 'test first' recommendation you approve.$tpl$,
    updated_at = now()
WHERE name = $tpl$Idea Validation$tpl$;

-- Retire the three platform templates nobody uses.
UPDATE public.workflow_library_templates
SET is_active = false,
    updated_at = now()
WHERE name IN ($tpl$Design Review$tpl$, $tpl$Product Launch$tpl$, $tpl$Client Project$tpl$);

-- Add a Planner to every kit that ships a rewritten template.
UPDATE public.project_kits
SET agent_roles = agent_roles || $tpl$[{"role": "Planner", "skills": [], "name_suggestion": "Planner"}]$tpl$::jsonb
WHERE name IN ($tpl$AI App / Agent$tpl$, $tpl$API / Backend$tpl$, $tpl$Design System$tpl$, $tpl$Game$tpl$, $tpl$Marketing Site$tpl$, $tpl$Mobile App$tpl$, $tpl$Web Application$tpl$)
  AND NOT agent_roles @> $tpl$[{"role": "Planner"}]$tpl$::jsonb;
